export interface EnumeratedCommand {
  /**
   * Dispatch action type, e.g. `"browser.scroll"` (template-resolved). The
   * stable identity of what the command does — lets a companion correlate a
   * spoken command with the action it triggers (the pattern is display text,
   * not an identifier).
   */
  action: string;
  /**
   * The ready-to-store keybind value when the command's action is
   * statically bindable — a concrete plugin action with no capture
   * template, no sequence, and no intrinsic phase. Absent otherwise.
   * This is what the Keybinds tab's bind-a-command flow copies.
   *
   * Declared 2026-09-19 (census). It was built here as a two-key
   * `serde_json::Map` and described in this comment; `KeybindBinding`
   * is that shape, and `RegistryEntry` is it plus combo and source.
   */
  binding?: KeybindBinding;
  /**
   * Optional grouping label from the command definition (e.g. "Navigation").
   */
  category?: string;
  /**
   * Optional human-readable "what it does / use case" text from the command
   * definition — the same field used as the HUD subtitle.
   */
  description?: string;
  dynamic: boolean;
  /**
   * Same as `owner_plugin` when dynamic; omitted when static. Surfaced
   * separately so callers can pattern-match `if let Some(owner) = ...`.
   */
  dynamic_owner?: string;
  /**
   * `<owner_plugin>:<display_pattern>` — stable across reloads.
   */
  id: string;
  owner_plugin: string;
  /**
   * Human-readable pattern (first option of each slot).
   */
  pattern: string;
  requires_tags: string[];
  sets_tags: string[];
}

export interface ExternalDisk {
  file_system?: string;
  /**
   * wire uint64 (64-bit) · min 0
   */
  free_bytes: number;
  is_removable: boolean;
  mount_point: string;
  name: string;
  /**
   * wire uint64 (64-bit) · min 0
   */
  total_bytes: number;
}

/**
 * Where a field appears in generic UI rendering. Each field on a
 * collection declares at most one role; surfaces (discovery HUD,
 * settings UI, etc.) interpret roles on their own terms.
 * 
 * See `docs/design/DESIGN_COLLECTION_FIELD_ROLES.md` for the full vocabulary
 * rationale. Roles `primary`, `secondary`, `group`, `description`,
 * `payload` are consumed by
 * `services::matching_service::expand_collections_to_items`
 * for discovery items; `summary` is consumed by the settings UI's
 * log-kind timeline rows.
 */
export type FieldDisplay = "primary" | "secondary" | "group" | "description" | "payload" | "summary";

/**
 * The declared shape of a single action-type field. See `ActionFieldSchema`.
 * 
 * Wire format uses snake_case strings (`"string"`, `"int"`, `"enum"`, …).
 * Unknown values fail deserialization — that's deliberate: a typo in
 * `plugin.json` should surface at load time, not at dispatch. The `Json`
 * variant is the documented escape hatch for shapes too dynamic to
 * declare statically.
 */
export type FieldType = "string" | "int" | "number" | "boolean" | "string[]" | "enum" | "object" | "json" | "secret_ref";

